1	import { useEffect, useRef } from "react";
2	import { Link } from "react-router-dom";
3	import { Compass, X, BookMarked, AlertCircle, FileText, BookOpen, ChevronRight, ClipboardCheck } from "lucide-react";
4	import { phaseById, stationKnowledgeFor, type Station } from "../data/stations";
5	import { concepts } from "../data/concepts";
6	import { leavesForStation, metaFor, colorForLeaf } from "../data/docTree";
7	import { iso13485LeavesByStation } from "../data/iso13485/docTree";
8	import { getIcon } from "../lib/icons";
9	import { renderRich } from "../lib/richText";
10	import { StatusChip } from "./StatusChip";
11	import { ConceptChip } from "./ConceptChip";
12	import { LevelMeter } from "./LevelMeter";
13	
14	/**
15	 * 정거장 상세 — 본문은 여기서만 (개요 오염 X).
16	 * 데스크톱 우측 480px drawer / 모바일 하단 풀시트. esc 닫기.
17	 */
18	export function StationDetail({
19	  station,
20	  onClose,
21	  certId,
22	}: {
23	  station: Station | null;
24	  onClose: () => void;
25	  certId?: "ivdr" | "iso13485";
26	}) {
27	  const panelRef = useRef<HTMLDivElement>(null);
28	  const open = station !== null;
29	
30	  useEffect(() => {
31	    if (!open) return;
32	    const onKey = (e: KeyboardEvent) => {
33	      if (e.key === "Escape") onClose();
34	    };
35	    document.addEventListener("keydown", onKey);
36	    // 열릴 때 패널로 포커스 이동 (키보드/스크린리더)
37	    panelRef.current?.focus();
38	    document.body.style.overflow = "hidden";
39	    return () => {
40	      document.removeEventListener("keydown", onKey);
41	      document.body.style.overflow = "";
42	    };
43	  }, [open, station, onClose]);
44	
45	  if (!station) return null;
46	
47	  const phase = phaseById(station.phase);
48	  const color = `var(${phase.colorVar})`;
49	  const Icon = getIcon(station.icon);
50	
51	  return (
52	    <div className="fixed inset-0 z-50" role="dialog" aria-modal="true" aria-labelledby="detail-title">
53	      {/* overlay */}
54	      <button
55	        type="button"
56	        aria-label="닫기"
57	        onClick={onClose}
58	        className="absolute inset-0 bg-[rgba(16,24,40,0.45)]"
59	      />
60	
61	      {/* 패널: 데스크톱 우측 / 모바일 하단 풀시트 */}
62	      <div
63	        ref={panelRef}
64	        tabIndex={-1}
65	        className="absolute bg-bg shadow-[var(--shadow-pop)] outline-none
66	                   inset-x-0 bottom-0 max-h-[88vh] rounded-t-[var(--r-lg)]
67	                   sm:inset-y-0 sm:right-0 sm:left-auto sm:max-h-none sm:w-[480px] sm:rounded-none sm:rounded-l-[var(--r-lg)]
68	                   overflow-y-auto"
69	        style={{ animation: "ivdr-slide 180ms ease-out" }}
70	      >
71	        {/* 상단 페이즈 색 띠 */}
72	        <div style={{ height: 4, background: color }} aria-hidden />
73	
74	        <div style={{ padding: "var(--s-6)" }}>
75	          {/* 헤더 */}
76	          <div className="flex items-start gap-3">
77	            <span
78	              className="inline-flex shrink-0 items-center justify-center rounded-full text-text-on-color font-bold"
79	              style={{ background: color, width: 36, height: 36, fontSize: "var(--t-base)" }}
80	            >
81	              {station.id}
82	            </span>
83	            <div className="min-w-0 flex-1">
84	              <div className="flex items-center gap-2">
85	                <Icon size={18} style={{ color }} aria-hidden />
86	                <span className="font-semibold" style={{ color, fontSize: "var(--t-sm)" }}>
87	                  Phase {phase.order} · {phase.title}
88	                </span>
89	              </div>
90	              <h2
91	                id="detail-title"
92	                className="font-extrabold text-text"
93	                style={{ fontSize: "var(--t-xl)", lineHeight: "var(--lh-tight)", marginTop: 4 }}
94	              >
95	                {station.title}
96	              </h2>
97	            </div>
98	            <button
99	              type="button"
100	              onClick={onClose}
101	              aria-label="상세 닫기"
102	              className="grid shrink-0 place-items-center rounded-[var(--r-sm)] text-text-muted hover:bg-surface"
103	              style={{ width: 40, height: 40 }}
104	            >
105	              <X size={22} aria-hidden />
106	            </button>
107	          </div>
108	
109	          <div style={{ marginTop: "var(--s-3)" }}>
110	            <StatusChip label={station.tag.label} tone={station.tag.tone} size="md" />
111	          </div>
112	
113	          {/* 📄 이 단계에서 써야 할 문서 (전체 리스트) */}
114	          {(() => {
115	            const docsForStation = certId === "iso13485"
116	              ? iso13485LeavesByStation(station.id)
117	              : leavesForStation(station.id);
118	            return (
119	              <div
120	                className="mt-4 overflow-hidden rounded-[var(--r-md)]"
121	                style={{ border: "1px solid var(--border)" }}
122	              >
123	                <div className="flex items-center gap-2" style={{ background: "var(--surface)", padding: "10px 12px" }}>
124	                  <FileText size={16} style={{ color: "var(--accent)" }} aria-hidden />
125	                  <span className="font-bold text-text" style={{ fontSize: "var(--t-sm)" }}>
126	                    이 단계에서 써야 할 문서
127	                  </span>
128	                  <span
129	                    className="rounded-full font-bold text-text-on-color"
130	                    style={{ background: "var(--accent)", fontSize: "var(--t-xs)", padding: "1px 8px" }}
131	                  >
132	                    {docsForStation.length}
133	                  </span>
134	                </div>
135	                <ul>
136	                  {docsForStation.map((l) => {
137	                    const m = metaFor(l.id);
138	                    const c = `var(${colorForLeaf(l.id)})`;
139	                    return (
140	                      <li key={l.id} style={{ borderTop: "1px solid var(--border)" }}>
141	                        <Link
142	                          to={`/doc/${l.id}`}
143	                          className="flex items-center gap-2 hover:bg-surface"
144	                          style={{ padding: "9px 12px" }}
145	                        >
146	                          <span aria-hidden className="inline-block shrink-0 rounded-full" style={{ width: 8, height: 8, background: c }} />
147	                          <span className="min-w-0 flex-1 font-semibold text-text" style={{ fontSize: "var(--t-sm)" }}>
148	                            {l.title}
149	                          </span>
150	                          {m && <LevelMeter kind="importance" level={m.importance} showLabel={false} />}
151	                          <ChevronRight size={15} style={{ color: "var(--text-subtle)" }} className="shrink-0" aria-hidden />
152	                        </Link>
153	                      </li>
154	                    );
155	                  })}
156	                </ul>
157	              </div>
158	            );
159	          })()}
160	
161	          {/* 🧭 지금 할 일 — accent 아님, 페이즈색 카드 */}
162	          <div
163	            className="rounded-[var(--r-md)]"
164	            style={{
165	              background: `var(${phase.tintVar})`,
166	              borderLeft: `4px solid ${color}`,
167	              padding: "var(--s-4)",
168	              marginTop: "var(--s-6)",
169	            }}
170	          >
171	            <div className="flex items-center gap-2" style={{ color }}>
172	              <Compass size={18} strokeWidth={2.25} aria-hidden />
173	              <span className="font-bold" style={{ fontSize: "var(--t-sm)" }}>
174	                지금 할 일
175	              </span>
176	            </div>
177	            <p className="text-text" style={{ fontSize: "var(--t-base)", marginTop: 6, fontWeight: 600 }}>
178	              {station.todo}
179	            </p>
180	          </div>
181	
182	          {/* ✅ 이 단계에서 알아야 할 정보 (체크리스트) */}
183	          {(() => {
184	            const knowledge = certId === "iso13485" ? [] : stationKnowledgeFor(station.id);
185	            return knowledge.length > 0 ? (
186	              <div
187	                className="rounded-[var(--r-md)] border"
188	                style={{ borderColor: "var(--border)", background: "var(--surface)", padding: "var(--s-4)", marginTop: "var(--s-4)" }}
189	              >
190	                <div className="flex items-center gap-2 text-text" style={{ marginBottom: "var(--s-2)" }}>
191	                  <ClipboardCheck size={18} style={{ color: "var(--info)" }} aria-hidden />
192	                  <span className="font-bold" style={{ fontSize: "var(--t-sm)" }}>
193	                    이 단계에서 알아야 할 정보
194	                  </span>
195	                </div>
196	                <ul className="flex flex-col" style={{ gap: 6 }}>
197	                  {knowledge.map((k, i) => (
198	                    <li
199	                      key={i}
200	                      className="flex items-start gap-2 text-text"
201	                      style={{ fontSize: "var(--t-sm)", lineHeight: "var(--lh-base)" }}
202	                    >
203	                      <span aria-hidden className="mt-0.5 shrink-0 font-bold" style={{ color: "var(--info)" }}>
204	                        ☐
205	                      </span>
206	                      <span>{k}</span>
207	                    </li>
208	                  ))}
209	                </ul>
210	              </div>
211	            ) : null;
212	          })()}
213	
214	          {/* 본문 */}
215	          <div style={{ marginTop: "var(--s-6)" }}>
216	            {station.body.map((p, i) => (
217	              <p
218	                key={i}
219	                className="text-text"
220	                style={{
221	                  fontSize: "var(--t-base)",
222	                  lineHeight: "var(--lh-base)",
223	                  marginBottom: "var(--s-4)",
224	                }}
225	              >
226	                {renderRich(p)}
227	              </p>
228	            ))}
229	          </div>
230	
231	          {/* 갈림길 (St2) */}
232	          {station.forks && (
233	            <div style={{ marginTop: "var(--s-2)" }}>
234	              <h3 className="font-bold text-text" style={{ fontSize: "var(--t-base)", marginBottom: "var(--s-3)" }}>
235	                갈림길 — 3갈래 경로
236	              </h3>
237	              <div className="flex flex-col gap-2">
238	                {station.forks.map((f) => (
239	                  <div
240	                    key={f.label}
241	                    className="rounded-[var(--r-md)] border"
242	                    style={{ borderColor: "var(--border)", padding: "var(--s-3)" }}
243	                  >
244	                    <div className="flex items-center gap-2">
245	                      <StatusChip label={f.label} tone={f.tone} />
246	                    </div>
247	                    <p className="text-text-muted" style={{ fontSize: "var(--t-sm)", marginTop: 6 }}>
248	                      {f.desc} <span className="text-text">→ {f.route}</span>
249	                    </p>
250	                  </div>
251	                ))}
252	              </div>
253	            </div>
254	          )}
255	
256	          {/* 비고 */}
257	          {station.note && (
258	            <div
259	              className="flex gap-2 rounded-[var(--r-md)]"
260	              style={{ background: "var(--warning-bg)", padding: "var(--s-3)", marginTop: "var(--s-4)" }}
261	            >
262	              <AlertCircle size={18} style={{ color: "var(--warning)" }} className="mt-0.5 shrink-0" aria-hidden />
263	              <p className="text-text" style={{ fontSize: "var(--t-sm)", lineHeight: "var(--lh-base)" }}>
264	                {renderRich(station.note)}
265	              </p>
266	            </div>
267	          )}
268	
269	          {/* 관련 개념 (양방향 연결) */}
270	          {(() => {
271	            const related = concepts.filter((c) => c.relatedStationIds.includes(station.id));
272	            if (related.length === 0) return null;
273	            return (
274	              <div style={{ marginTop: "var(--s-6)" }}>
275	                <div className="flex items-center gap-2 text-text-muted" style={{ marginBottom: "var(--s-2)" }}>
276	                  <BookOpen size={16} aria-hidden />
277	                  <span className="font-semibold" style={{ fontSize: "var(--t-sm)" }}>
278	                    관련 개념
279	                  </span>
280	                </div>
281	                <div className="flex flex-wrap gap-2">
282	                  {related.map((c) => (
283	                    <ConceptChip key={c.slug} slug={c.slug} />
284	                  ))}
285	                </div>
286	              </div>
287	            );
288	          })()}
289	
290	          {/* 관련 조항 */}
291	          <div style={{ marginTop: "var(--s-6)" }}>
292	            <div className="flex items-center gap-2 text-text-muted" style={{ marginBottom: "var(--s-2)" }}>
293	              <BookMarked size={16} aria-hidden />
294	              <span className="font-semibold" style={{ fontSize: "var(--t-sm)" }}>
295	                관련 조항
296	              </span>
297	            </div>
298	            <ul className="flex flex-wrap gap-2">
299	              {station.refs.map((r) => (
300	                <li
301	                  key={r}
302	                  className="rounded-[var(--r-sm)] font-mono text-text-muted"
303	                  style={{
304	                    background: "var(--surface)",
305	                    border: "1px solid var(--border)",
306	                    fontSize: "var(--t-xs)",
307	                    padding: "4px 8px",
308	                  }}
309	                >
310	                  {r}
311	                </li>
312	              ))}
313	            </ul>
314	          </div>
315	        </div>
316	      </div>
317	    </div>
318	  );
319	}
