1	import type { Phase, Station } from "../data/stations";
2	import { StationCard } from "./StationCard";
3	
4	/**
5	 * 페이즈 색 밴드 + 라벨 + 카드들.
6	 * 틴트 배경으로 그룹을 즉시 인지 (게슈탈트 공통영역).
7	 */
8	export function PhaseBand({
9	  phase,
10	  stations,
11	  activeId,
12	  onOpen,
13	  registerRef,
14	}: {
15	  phase: Phase;
16	  stations: Station[];
17	  activeId?: number;
18	  onOpen: (id: number) => void;
19	  registerRef?: (el: HTMLElement | null) => void;
20	}) {
21	  const color = `var(${phase.colorVar})`;
22	  const tint = `var(${phase.tintVar})`;
23	
24	  return (
25	    <section
26	      ref={registerRef}
27	      id={`phase-${phase.id}`}
28	      aria-labelledby={`phase-${phase.id}-title`}
29	      className="scroll-mt-24 rounded-[var(--r-lg)]"
