// ivdr-wiki/src/data/ivdd/stations.ts

export type IVDDPhaseId = "ivdd-classify" | "ivdd-docs" | "ivdd-assess" | "ivdd-cert";

export interface IVDDPhase {
  id: IVDDPhaseId;
  order: number;
  title: string;
  subtitle: string;
  colorVar: string;
  tintVar: string;
}

export interface IVDDStation {
  id: number;
  phase: IVDDPhaseId;
  title: string;
  icon: string;
  oneLine: string;
  tag: { label: string; tone: "neutral" | "info" | "warning" | "danger" | "success" };
  body: string[];
  todo: string;
  refs: string[];
  note?: string;
}

export const ivddPhases: IVDDPhase[] = [
  { id: "ivdd-classify", order: 1, title: "준비 · 분류",    subtitle: "기기 분류 결정 및 적합성 전략 수립",    colorVar: "--p2", tintVar: "--p2-tint" },
  { id: "ivdd-docs",     order: 2, title: "기술 문서",       subtitle: "기술문서·성능·위험분석 작성",           colorVar: "--p3", tintVar: "--p3-tint" },
  { id: "ivdd-assess",   order: 3, title: "적합성 평가",     subtitle: "품질시스템 심사 및 경로 이행",          colorVar: "--p4", tintVar: "--p4-tint" },
  { id: "ivdd-cert",     order: 4, title: "CE 마킹 & 사후", subtitle: "선언서 발행 및 시판 후 감시",           colorVar: "--p1", tintVar: "--p1-tint" },
];

export const ivddPhaseById = (id: IVDDPhaseId): IVDDPhase =>
  ivddPhases.find((p) => p.id === id)!;

export const ivddStationsByPhase = (): Record<IVDDPhaseId, IVDDStation[]> => {
  const map = {} as Record<IVDDPhaseId, IVDDStation[]>;
  for (const p of ivddPhases) {
    map[p.id] = ivddStations.filter((s) => s.phase === p.id);
  }
  return map;
};

