import type { Phase, Station, PhaseId } from "../data/stations";

function adaptPhase(p: typeof ivddPhases[0]): Phase {
  return { ...p, id: p.id as unknown as PhaseId };
}

function adaptStation(s: typeof ivddStations[0]): Station {
  return { ...s, phase: s.phase as unknown as PhaseId };
}

export function IVDDMap() {
  const navigate = useNavigate();
  const { id } = useParams();

  const adaptedPhases = useMemo(() => ivddPhases.map(adaptPhase), []);
  const adaptedStations = useMemo(() => ivddStations.map(adaptStation), []);

  const stationsByPhase = useMemo(() => {
    const map = {} as Record<string, Station[]>;
    for (const p of adaptedPhases) {
      map[p.id] = adaptedStations.filter((s) => s.phase === p.id);
    }
    return map;
  }, [adaptedPhases, adaptedStations]);

  const openId = id ? Number(id) : null;
  const activeStation =
    openId != null
      ? adaptedStations.find((s) => s.id === openId) ?? null
      : null;

  const openStation = useCallback(
    (sid: number) => navigate(`/ivdd/station/${sid}`),
    [navigate],
  );
  const closeStation = useCallback(() => navigate("/ivdd"), [navigate]);

  const [activePhase, setActivePhase] = useState<IVDDPhaseId | null>("ivdd-classify");
  const bandRefs = useRef<Map<string, HTMLElement>>(new Map());

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) {
          const pid = (visible.target as HTMLElement).dataset
            .phase as IVDDPhaseId;
          if (pid) setActivePhase(pid);
        }
      },
      { rootMargin: "-45% 0px -45% 0px", threshold: [0, 0.25, 0.5, 1] },
    );
    bandRefs.current.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  return (
    <div className="min-h-screen bg-bg">
      <PhaseNav
        activePhase={activePhase as unknown as PhaseId}
        overridePhases={adaptedPhases}
      />

      <main
        className="mx-auto"
        style={{
          maxWidth: "var(--max-w)",
          padding: "var(--s-12) var(--margin) var(--s-16)",
        }}
      >
        {/* IVDR 전환 경고 배너 */}
        <div
          className="rounded-[var(--r-md)]"
          style={{
            background: "var(--warning-bg)",
            borderLeft: "4px solid var(--warning)",
            padding: "var(--s-3) var(--s-5)",
            marginBottom: "var(--s-6)",
            display: "flex",
            gap: "var(--s-3)",
            alignItems: "flex-start",
          }}
        >
          <span style={{ fontSize: "var(--t-lg)" }}>⚠️</span>
          <div>
            <span
              className="font-bold"
              style={{ color: "var(--warning)", fontSize: "var(--t-sm)" }}
            >
              IVDR 전환 중
            </span>
            <p
              style={{
                fontSize: "var(--t-sm)",
                color: "var(--text)",
                marginTop: 2,
              }}
            >
              98/79/EC(IVDD)는 IVDR(2017/746)로 대체됩니다. 레거시 기기 전환 마감: Class D → 2025.5.26 · Class C → 2026.5.26 · Class A/B → 2027.5.26
            </p>
          </div>
        </div>

        {/* 페이지 헤더 */}
        <header style={{ textAlign: "center", marginBottom: "var(--s-10)", paddingTop: "var(--s-6)" }}>
          <span
            style={{
              fontSize: "var(--t-xs)",
              background: "var(--p2-tint)",
              color: "var(--p2)",
              borderRadius: "var(--r-full)",
              padding: "4px 14px",
              fontWeight: 700,
            }}
          >
            EU 지침 98/79/EC
          </span>
          <h1
            style={{
              fontSize: "var(--t-3xl)",
              fontWeight: 900,
              color: "var(--text)",
              marginTop: "var(--s-3)",
            }}
          >
            IVDD 여정
          </h1>
          <p
            style={{
              fontSize: "var(--t-base)",
              color: "var(--text-muted)",
              marginTop: "var(--s-2)",
            }}
          >
            EU IVD Directive (IVDR 전환 전 레거시 경로) · 5단계 · 7 정거장 · 9개 문서
          </p>

          <div className="flex flex-wrap justify-center gap-3" style={{ marginTop: "var(--s-6)" }}>
            <Link
              to="/documents"
              className="inline-flex items-center gap-2 rounded-[var(--r-md)] font-bold text-text-on-color"
              style={{
                background: "var(--p2)",
                fontSize: "var(--t-sm)",
                padding: "11px 18px",
                minHeight: 44,
              }}
            >
              <FolderTree size={18} aria-hidden />
              공통 문서 전체 보기
            </Link>
            <Link
              to="/wiki"
              className="inline-flex items-center gap-2 rounded-[var(--r-md)] border font-bold text-text hover:bg-surface"
              style={{
                borderColor: "var(--border-strong)",
                fontSize: "var(--t-sm)",
                padding: "11px 18px",
                minHeight: 44,
              }}
            >
              <Library size={18} style={{ color: "var(--info)" }} aria-hidden />
              개념 위키
            </Link>
            <Link
              to="/"
              className="inline-flex items-center gap-2 rounded-[var(--r-md)] border font-bold text-text-muted hover:bg-surface"
              style={{
                borderColor: "var(--border)",
                fontSize: "var(--t-sm)",
                padding: "11px 18px",
                minHeight: 44,
              }}
            >
              ← 인증 허브
            </Link>
          </div>
        </header>

        {/* 4 페이즈 밴드 */}
        <div className="flex flex-col" style={{ gap: "var(--s-8)" }}>
          {adaptedPhases.map((p) => (
            <PhaseBand
              key={p.id}
              phase={p}
              stations={stationsByPhase[p.id] ?? []}
              activeId={openId ?? undefined}
              onOpen={openStation}
              registerRef={(el) => {
                if (el) {
                  el.dataset.phase = p.id;
                  bandRefs.current.set(p.id, el);
                } else {
                  bandRefs.current.delete(p.id);
                }
              }}
            />
          ))}
        </div>

        <footer
          className="text-text-subtle"
          style={{
            fontSize: "var(--t-xs)",
            marginTop: "var(--s-12)",
            lineHeight: "var(--lh-base)",
          }}
        >
          98/79/EC(IVDD) 내용은 2026년 6월 기준 확인값입니다. 실제 인증 진행 시 최신 규정 원문·인증기관 요건으로 재확인하세요.
        </footer>
      </main>

      {/* 스테이션 상세 — IVDD 문서 목록은 DrawerExtra로 별도 주입 */}
      <StationDetail station={activeStation} onClose={closeStation} />

      {/* IVDD 문서 목록 오버레이 보조 패널 (StationDetail certId 확장 전까지 임시) */}
      {activeStation && (
        <IVDDDocListOverlay stationId={activeStation.id} />
      )}
    </div>
  );
}

/**
 * IVDD 정거장별 문서 목록을 StationDetail 외부에서 표시.
 * StationDetail이 IVDD certId를 지원하지 않으므로,
 * 열린 스테이션의 문서 목록을 별도 인포메이션 배너로 제공한다.
 * (화면에는 StationDetail drawer 하단에 위치)
 */
function IVDDDocListOverlay({ stationId }: { stationId: number }) {
  const docs = ivddLeavesByStation(stationId);
  if (docs.length === 0) return null;

  const toneColor: Record<string, string> = {
    required: "var(--p2)",
    conditional: "var(--info)",
    ifApplicable: "var(--text-subtle)",
  };

  const toneLabel: Record<string, string> = {
    required: "필수",
    conditional: "조건부",
    ifApplicable: "해당 시",
  };

  return (
    <div
      className="fixed z-50 pointer-events-none"
      style={{
        bottom: "var(--s-6)",
        right: "calc(480px + var(--s-4))",
        width: 280,
      }}
    >
      <div
        className="rounded-[var(--r-lg)] pointer-events-auto"
        style={{
          background: "var(--bg)",
          border: "1px solid var(--border-strong)",
          boxShadow: "var(--shadow-pop)",
          overflow: "hidden",
        }}
      >
        <div
          className="flex items-center gap-2"
          style={{
            background: "var(--p2-tint)",
            padding: "var(--s-2) var(--s-3)",
            borderBottom: "1px solid var(--border)",
          }}
        >
          <Award size={14} style={{ color: "var(--p2)" }} aria-hidden />
          <span
            className="font-bold"
            style={{ fontSize: "var(--t-xs)", color: "var(--p2)" }}
          >
            IVDD 관련 문서 ({docs.length})
          </span>
        </div>
        <ul>
          {docs.map((doc, idx) => (
            <li
              key={doc.id}
              style={{
                borderTop: idx === 0 ? "none" : "1px solid var(--border)",
                padding: "var(--s-2) var(--s-3)",
              }}
            >
              <div className="flex items-start gap-2">
                <span
                  className="inline-block shrink-0 rounded-full"
                  style={{
                    width: 8,
                    height: 8,
                    marginTop: 5,
                    background: toneColor[doc.requirement] ?? "var(--text-subtle)",
                  }}
                  aria-hidden
                />
                <div className="min-w-0 flex-1">
                  <p
                    className="font-semibold text-text"
                    style={{ fontSize: "var(--t-xs)", lineHeight: "1.4" }}
                  >
                    {doc.title}
                  </p>
                  <div className="flex items-center gap-1" style={{ marginTop: 2 }}>
                    <span
                      className="rounded font-bold"
                      style={{
                        fontSize: 10,
                        padding: "1px 5px",
                        background: toneColor[doc.requirement] ?? "var(--surface)",
                        color: "var(--text-on-color)",
                      }}
                    >
                      {toneLabel[doc.requirement] ?? doc.requirement}
                    </span>
                    {doc.note && (
                      <span
                        className="text-text-subtle"
                        style={{ fontSize: 10 }}
                      >
                        {doc.note}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
